description:
Objective:
Add the SQLite persistence layer: `openDatabase`, `withTransaction` (atomic
unit-of-work with automatic rollback on throw), and `initSchema`. This satisfies
epic acceptance #2 (transactional write/rollback test).

Files:
- Create: `packages/core/src/persistence/db.ts`
- Create: `packages/core/src/persistence/schema.ts`
- Modify: `packages/core/package.json` (add deps)
- Modify: `packages/core/src/index.ts`
- Test:   `packages/core/test/persistence.test.ts`

Steps:

1. Add deps to `packages/core/package.json` — add a `dependencies` and extend
   `devDependencies` block so it reads:
```json
  "dependencies": { "better-sqlite3": "^11.3.0" },
  "devDependencies": { "@types/better-sqlite3": "^7.6.11" }
```
   Then install.
   Command: `npm install`
   Expected: better-sqlite3 builds/installs, exit 0.

2. Write the failing test `packages/core/test/persistence.test.ts`:
```ts
import { describe, expect, it } from 'vitest';
import { openDatabase, withTransaction } from '../src/persistence/db.js';
import { initSchema, SCHEMA_VERSION } from '../src/persistence/schema.js';

describe('persistence', () => {
  it('initSchema records the schema version', () => {
    const db = openDatabase(':memory:');
    initSchema(db);
    const row = db
      .prepare('SELECT value FROM meta WHERE key = ?')
      .get('schema_version') as { value: string } | undefined;
    expect(row?.value).toBe(String(SCHEMA_VERSION));
    db.close();
  });

  it('withTransaction commits on success', () => {
    const db = openDatabase(':memory:');
    initSchema(db);
    withTransaction(db, (d) =>
      d.prepare('INSERT INTO meta(key, value) VALUES (?, ?)').run('a', '1'),
    );
    const row = db.prepare('SELECT value FROM meta WHERE key = ?').get('a') as
      | { value: string }
      | undefined;
    expect(row?.value).toBe('1');
    db.close();
  });

  it('withTransaction rolls back when the function throws', () => {
    const db = openDatabase(':memory:');
    initSchema(db);
    expect(() =>
      withTransaction(db, (d) => {
        d.prepare('INSERT INTO meta(key, value) VALUES (?, ?)').run('b', '2');
        throw new Error('boom');
      }),
    ).toThrow('boom');
    const row = db.prepare('SELECT value FROM meta WHERE key = ?').get('b');
    expect(row).toBeUndefined();
    db.close();
  });
});
```

3. Run the test to verify it FAILS.
   Command: `npx vitest run packages/core/test/persistence.test.ts`
   Expected: FAIL — cannot resolve `../src/persistence/db.js`.

4. Create `packages/core/src/persistence/db.ts`:
```ts
import Database from 'better-sqlite3';

export type Db = Database.Database;

export function openDatabase(path: string): Db {
  const db = new Database(path);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  return db;
}

export function withTransaction<T>(db: Db, fn: (db: Db) => T): T {
  const txn = db.transaction(fn);
  return txn(db);
}
```

5. Create `packages/core/src/persistence/schema.ts`:
```ts
import type { Db } from './db.js';

export const SCHEMA_VERSION = 1;

export function initSchema(db: Db): void {
  db.exec(
    'CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);',
  );
  db.prepare('INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)').run(
    'schema_version',
    String(SCHEMA_VERSION),
  );
}
```

6. Add to `packages/core/src/index.ts` (append):
```ts
export { openDatabase, withTransaction } from './persistence/db.js';
export type { Db } from './persistence/db.js';
export { initSchema, SCHEMA_VERSION } from './persistence/schema.js';
```

7. Run the test to verify it PASSES.
   Command: `npx vitest run packages/core/test/persistence.test.ts`
   Expected: 3 passed (including rollback assertion).

8. Typecheck.
   Command: `npm run build`
   Expected: exit 0.

9. Commit.
   Command: `git add -A && git commit -m "feat(e0): SQLite persistence with atomic withTransaction"`
